const passthrough = (value) => value;
const Type = {
  Object: (shape) => ({ kind: 'object', shape }),
  Optional: passthrough,
  Array: passthrough,
  Union: (items) => ({ kind: 'union', items }),
  Literal: passthrough,
  Number: (opts) => ({ kind: 'number', ...opts }),
  Boolean: (opts) => ({ kind: 'boolean', ...opts }),
  String: (opts) => ({ kind: 'string', ...opts }),
};
module.exports = { Type };
